import{z as o,x as s,o as A,c as m,q as l,j as r,D as e,d as t,s as i,S as n,b as a}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"投机与批处理的交互","description":"","frontmatter":{"title":"投机与批处理的交互","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/spec-batching-interaction.md","filePath":"llm/spec-batching-interaction.md","lastUpdated":1791063341000}'),d={name:"llm/spec-batching-interaction.md"};function p(c,E,C,h,F,D){const B=s("Mermaid");return A(),m("div",null,[E[2]||(E[2]=l('<h1 id="投机与批处理的交互" tabindex="-1">投机与批处理的交互 <a class="header-anchor" href="#投机与批处理的交互" aria-label="Permalink to &quot;投机与批处理的交互&quot;">​</a></h1><div class="epigraph"><p>批量与投机在填同一块空闲算力：谁先把 GPU 填满，谁就让对方变得多余。</p><footer>—— 据 Leviathan et al., 2023 的带宽墙论证与 EAGLE-3 的批量实验口径整理</footer></div><p><a href="/llm/spec-online-draft-selection">上一课</a>解决了「这条请求用哪个草稿」；本课看另一根轴：批量。<a href="/llm/speculative-decoding">投机解码原理</a>的收益论证建立在 decode 的带宽墙上——一次稍胖的校验前向近乎免费；<a href="/llm/kv-speculative-interaction">KV 与投机解码</a>管住了缓存的峰值与回滚。剩下的问题是规模：论文的加速比多在 batch=1 报出，服务却跑在批量几十到几百。本课写批处理怎么把这笔账重算，以及树宽与批量为什么此消彼长。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Roofline 上 decode 有两段人生。批量小的时候，每步读一遍权重只服务一个 token，算术强度低，GPU 卡在带宽墙上：校验前向多吃 \\(\\gamma\\) 个位置的 FLOPs 几乎不花时间，投机白捡。批量大的时候，\\(B\\) 条请求的查询行拼在一起，权重一次读入摊给 \\(B\\) 份算，算术强度随 \\(B\\) 线上爬，GPU 逼近算力屋顶：此时校验的 \\(\\gamma\\) 个额外位置按真实 FLOPs 计价，一次「稍胖」前向真的胖了。固定在 batch=1 的直觉搬进高并发服务，会观察到加速比蒸发甚至转负——投机赚的步数被校验的算力账一块块退还。树让这事更陡：\\(N\\) 个节点在校验里就是 \\(N\\) 个位置，批量与树宽相乘。</p><p><span class="marginnote">数字实例：设权重一次读入 16 GB、显存带宽 2 TB/s，单次前向光搬权重就要 8 ms。batch=1 时这 8 ms 只服务 1 个 token，校验多算 \\(\\gamma\\) 个位置几乎不添时间；batch=64 时同一份 8 ms 摊给 64 条请求，GPU 开始缺算力，多出来的位置才真正按 FLOPs 计价。</span></p><p><span class="marginnote">术语翻译：「算术强度」就是每搬 1 字节内存，能摊上多少次乘加运算——decode 单步读一整份权重却只产出 1 个 token，像一辆重卡只运一件小货；批量是把车斗堆满的拼单，拼满之后，「多带一件货」（校验加宽）才开始收费。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>先算再开</strong>。判据仍是「每单位目标前向时间的期望前进」，但 \\(c_{\\mathrm{tgt}}\\) 要按当前批量测：同一条草稿在 \\(B=1\\) 时 \\(c_{\\mathrm{tgt}}\\approx 1\\)，在算力屋顶附近 \\(c_{\\mathrm{tgt}}\\) 趋向 \\(1+\\gamma\\)（或树节点数）。在线侧把它并进上一课的桶账：批量大到校验不再免费时，缩 \\(\\gamma\\)、收树宽，或者关。<strong>参差管理</strong>。投机使同一 iter 内各请求的产出变成随机变量：接受长的多写、拒绝的只写修正 token，批内进度参差。稳定做法是 iter 边界对齐「一次校验前向」，接受长度只改本请求进度不改 iter 切分，新请求仍在校验点插入（连续批的成员边界与 <a href="/llm/kv-speculative-interaction">KV 与投机解码</a>的提交协议对齐）。<strong>混合批</strong>。允许同批混投机与非投机请求时，校验核按本批最大草稿深度开形状、短请求掩码早退，避免为空气算注意力。</p>',9)),(A(),r(n,null,{default:e(()=>[i(B,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20MON%5B%22%E7%9B%91%E6%8E%A7%EF%BC%9A%E5%BD%93%E5%89%8D%E6%89%B9%E9%87%8F%E4%B8%8E%E7%AE%97%E6%9C%AF%E5%BC%BA%E5%BA%A6%22%5D%20--%3E%20ROOF%7B%22%E6%98%AF%E5%90%A6%E9%80%BC%E8%BF%91%E7%AE%97%E5%8A%9B%E5%B1%8B%E9%A1%B6%22%7D%0A%20%20ROOF%20--%3E%7C%22%E5%B8%A6%E5%AE%BD%E5%A2%99%EF%BC%9A%E6%A0%A1%E9%AA%8C%E8%BF%91%E5%85%8D%E8%B4%B9%22%7C%20FULL%5B%22%E5%85%A8%E6%A0%91%E5%AE%BD%20%2B%20%E5%A4%A7%20%CE%B3%22%5D%0A%20%20ROOF%20--%3E%7C%22%E7%AE%97%E5%8A%9B%E5%A2%99%EF%BC%9A%E6%A0%A1%E9%AA%8C%E8%AE%A1%E4%BB%B7%22%7C%20SHRINK%5B%22%E7%BC%A9%E6%A0%91%E5%AE%BD%20%2F%20%E5%87%8F%20%CE%B3%22%5D%0A%20%20SHRINK%20--%3E%20NEG%7B%22%E8%B4%A6%E4%B8%8A%E4%BB%8D%E5%87%80%E4%BA%8F%3F%22%7D%0A%20%20NEG%20--%3E%7C%22%E6%98%AF%22%7C%20OFFB%5B%22%E6%9C%AC%E6%89%B9%E5%85%B3%E6%8A%95%E6%9C%BA%22%5D%0A%20%20NEG%20--%3E%7C%22%E5%90%A6%22%7C%20KEEP%5B%22%E4%BF%9D%E7%95%99%E7%BC%A9%E5%B0%8F%E7%9A%84%E6%A0%91%22%5D%0A%20%20FULL%20--%3E%20DONE%5B%22%E6%AF%8F%E8%BD%AE%E6%8C%89%20%CF%84%20%E6%8F%90%E4%BA%A4%22%5D%0A%20%20KEEP%20--%3E%20DONE%0A%20%20OFFB%20--%3E%20DONE%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[t(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("h2",{id:"机制",tabindex:"-1"},[t("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=a("p",null,"批量与投机互替的机制可以一句话钉死：两者都在消耗「decode 算不满算力屋顶」这同一份余量。批量用 \\(B\\) 条序列填，投机用一条序列的 \\(\\gamma+1\\) 个位置填；余量被谁先吃掉，另一个的边际收益就归零。所以正确的问法不是「开不开投机」，而是「余量还剩多少、给谁」：低批量延迟敏感的路由，余量天然在，投机是最大赢家；高批量吞吐优先的路由，余量已被批量吃掉，投机的正确形态是缩到只剩 \\(\\gamma=1\\) 的自投机头，或者干脆关。反例也有价值：SGLang 上 EAGLE-3 在 batch 64 仍报约四成吞吐提升——前提是树验证被融进连续批的调度与内核，形状不满算的开销被真正摊掉；这恰说明决定收益的是实现吃没吃掉余量，不是「批量必然杀死投机」。",-1)),E[5]||(E[5]=a("p",null,[a("span",{class:"marginnote"},"加速比的分母里有 \\(c_{\\mathrm{tgt}}\\)，而 \\(c_{\\mathrm{tgt}}\\) 是批量的函数。两张加速比表若批量不同，中间差的不只是噪声，是制度。跨批量外推加速比，等于假设 GPU 永远卡在带宽墙上。")],-1)),(A(),r(n,null,{default:e(()=>[i(B,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20B%5B%22%E6%9C%AC%E6%89%B9%E8%AF%B7%E6%B1%82%E5%88%B0%E8%BE%BE%20iter%20%E8%BE%B9%E7%95%8C%22%5D%20--%3E%20D%5B%22%E8%AF%BB%E5%90%84%E8%AF%B7%E6%B1%82%E8%8D%89%E7%A8%BF%E6%B7%B1%E5%BA%A6%3A%203%20%2F%202%20%2F%200%22%5D%0A%20%20D%20--%3E%20P%5B%22%E6%8C%89%E6%89%B9%E5%86%85%E6%9C%80%E5%A4%A7%E6%B7%B1%E5%BA%A6%E5%BC%80%E6%A0%B8%E5%BD%A2%E7%8A%B6%2C%20%E7%BB%9F%E4%B8%80%E4%B8%80%E6%AC%A1%E6%A0%A1%E9%AA%8C%E5%89%8D%E5%90%91%22%5D%0A%20%20P%20--%3E%20V%5B%22%E6%A0%A1%E9%AA%8C%E5%89%8D%E5%90%91%E8%B7%91%E5%AE%8C%E6%95%B4%E6%89%B9%22%5D%0A%20%20V%20--%3E%20M%7B%22%E6%9C%AC%E8%AF%B7%E6%B1%82%E6%9C%89%E8%8D%89%E7%A8%BF%E4%BD%8D%E5%90%97%3F%22%7D%0A%20%20M%20--%3E%7C%22%E6%B7%B1%E5%BA%A6%200%3A%20%E9%9D%9E%E6%8A%95%E6%9C%BA%E8%AF%B7%E6%B1%82%22%7C%20X%5B%22%E6%8E%A9%E7%A0%81%E6%97%A9%E9%80%80%2C%20%E4%B8%8D%E4%B8%BA%E7%A9%BA%E6%B0%94%E7%AE%97%E6%B3%A8%E6%84%8F%E5%8A%9B%22%5D%0A%20%20M%20--%3E%7C%22%E6%B7%B1%E5%BA%A6%202%20%E6%88%96%203%3A%20%E6%8A%95%E6%9C%BA%E8%AF%B7%E6%B1%82%22%7C%20Y%5B%22%E5%90%84%E6%8C%89%E8%87%AA%E5%B7%B1%E6%8E%A5%E5%8F%97%E9%95%BF%E5%BA%A6%E6%8F%90%E4%BA%A4%22%5D%0A%20%20X%20--%3E%20N%5B%22%E5%85%A8%E9%83%A8%E5%AF%B9%E9%BD%90%E5%88%B0%E4%B8%8B%E4%B8%80%E6%AC%A1%E6%A0%A1%E9%AA%8C%E8%BE%B9%E7%95%8C%22%5D%0A%20%20Y%20--%3E%20N%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[t(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=l('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>关投机的门槛不要拍脑袋：\\(\\alpha\\) 高的桶在中等批量下仍可能净赚，逐桶联评（上一课的账）而不是全局开关。p99 的账与均值不同：投机加大单步校验时间，TPOT 方差随 \\(\\alpha\\) 的随机性放大，SLO 按 p99 编时要给校验峰值留量。PD 分离架构里投机几乎全落在解码侧，预填池不为此扩容，但解码池的 KV 峰值预算要乘 \\((1+\\gamma)\\)——这笔账在 <a href="/llm/kv-speculative-interaction">KV 与投机解码</a>已编，本课只提醒它与批量预算是同一张表。最后，论文数字钉论文设定：batch=1 的峰值不是服务数字，高批量的吞吐数字也不能反过来说单请求延迟不赚。</p><p><span class="marginnote">常见误区：初学者容易以为「开了投机就必然更快」。批量爬高后余量被填满，收益会一路缩水甚至转负。正确顺序是先看当前批量落在 roofline 哪一段，再决定开多大 \\(\\gamma\\)、多宽的树——而不是先开再看运气。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>decode 在 roofline 上有两段：带宽墙下校验近免费，算力屋顶下校验按 FLOPs 计价，加速比随批量衰减。</li><li>批量与投机互替：都在消耗同一份「算不满」的余量，余量给谁要看延迟还是吞吐优先。</li><li>iter 边界对齐一次校验前向；接受长度只改请求进度；同批变长形状用掩码早退。</li><li>树宽与批量相乘进校验账，高批量下缩树是常态而非失败。</li><li>SLO 按 p99 编：投机的 TPOT 方差由接受长度的随机性贡献。</li><li>出处：Leviathan et al., ICML 2023；Li et al., <em>EAGLE-3</em>, 2025（SGLang batch 64 口径）；据本仓库投机课序整理。</li></ul>',5))])}const _=o(d,[["render",p]]);export{f as __pageData,_ as default};
